andom(20)\n        crit = d20 == 20\n        msg = msg .. (d20 + a.hit) .. \" to hit (d20 \" .. d20 .. (crit and \" CRIT\" or d20 == 1 and \" FUMBLE\" or \"\") .. \")  \"\n    end\n    if a.dmg then\n        local total, detail = roll(a.dmg)\n        if crit then\n            local extra = roll(a.dmg:gsub(\"[%+%-]%d+$\", \"\"))\n            total, detail = total + extra, detail .. \" +crit \" .. extra\n        end\n        msg = msg .. total .. (a.hit and \" dmg \" or \" \") .. detail .. \"  \"\n    end\n    msg = msg .. \"(\" .. a.note .. \")\"\n    if a.hit and self.RPGFigurine then self.RPGFigurine.attack() end\n    broadcastToColor(msg, \"Black\", { 1, 0.8, 0.4 })\n    if player.color ~= \"Black\" then broadcastToColor(msg, player.color, { 1, 0.8, 0.4 }) end\nend\n",["LuaScriptState"]="{\"name\": \"Sewer hunter\", \"hp\": 14, \"max\": 14, \"def\": 13, \"down\": false, \"attacks\": [{\"name\": \"Short bow\", \"hit\": 4, \"dmg\": \"1d8\", \"note\": \"range 10\"}]}",["XmlUI"]="",["Tags"]={"scene"},["GUID"]="b579ed",["grid"]={["x"]=6.8,["z"]=-2.6,["k"]="fig"}},{["Name"]="rpg_WOLF",["Transform"]={["posX"]=0.0,["posY"]=1.0,["posZ"]=0.0,["rotX"]=0.0,["rotY"]=270.0,["rotZ"]=0.0,["scaleX"]=1.0,["scaleY"]=1.0,["scaleZ"]=1.0},["Nickname"]="Fresh carcass",["Description"]="",["GMNotes"]="Food.",["ColorDiffuse"]={["r"]=1.0,["g"]=1.0,["b"]=1.0},["Locked"]=false,["Grid"]=false,["Snap"]=true,["Autoraise"]=true,["Sticky"]=true,["Tooltip"]=true,["HideWhenFaceDown"]=false,["Hands"]=false,["LuaScript"]="",["LuaScriptState"]="",["XmlUI"]="",["Tags"]={"scene"},["GUID"]="3f8191",["grid"]={["x"]=5,["z"]=-2.5,["k"]="fig"},["RPGdead"]=true},{["Name"]="rpg_WOLF",["Transform"]={["posX"]=0.0,["posY"]=1.0,["posZ"]=0.0,["rotX"]=0.0,["rotY"]=270.0,["rotZ"]=0.0,["scaleX"]=1.0,["scaleY"]=1.0,["scaleZ"]=1.0},["Nickname"]="Fresh carcass",["Description"]="",["GMNotes"]="Food.",["ColorDiffuse"]={["r"]=1.0,["g"]=1.0,["b"]=1.0},["Locked"]=false,["Grid"]=false,["Snap"]=true,["Autoraise"]=true,["Sticky"]