"]="https://raw.githubusercontent.com/Wngui/giants-of-holst/0ad34d333bbe38078e8545e19f36486a22565863/props/debris.obj",["DiffuseURL"]="https://raw.githubusercontent.com/Wngui/giants-of-holst/0ad34d333bbe38078e8545e19f36486a22565863/props/tex_graveyard.png",["NormalURL"]="",["ColliderURL"]="https://raw.githubusercontent.com/Wngui/giants-of-holst/0ad34d333bbe38078e8545e19f36486a22565863/props/collider_flat.obj",["Convex"]=true,["MaterialIndex"]=1,["TypeIndex"]=0,["CastShadows"]=true}},{["Name"]="rpg_THIEF",["Transform"]={["posX"]=0.0,["posY"]=1.0,["posZ"]=0.0,["rotX"]=0.0,["rotY"]=90.0,["rotZ"]=0.0,["scaleX"]=1.0,["scaleY"]=1.0,["scaleZ"]=1.0},["Nickname"]="Fallen guildsman",["Description"]="",["GMNotes"]="Died fighting.",["ColorDiffuse"]={["r"]=1.0,["g"]=1.0,["b"]=1.0},["Locked"]=false,["Grid"]=false,["Snap"]=true,["Autoraise"]=true,["Sticky"]=true,["Tooltip"]=true,["HideWhenFaceDown"]=false,["Hands"]=false,["LuaScript"]="",["LuaScriptState"]="",["XmlUI"]="",["Tags"]={"scene"},["GUID"]="af910a",["grid"]={["x"]=-3,["z"]=2,["k"]="fig"},["RPGdead"]=true},{["Name"]="rpg_THIEF",["Transform"]={["posX"]=0.0,["posY"]=1.0,["posZ"]=0.0,["rotX"]=0.0,["rotY"]=90.0,["rotZ"]=0.0,["scaleX"]=1.0,["scaleY"]=1.0,["scaleZ"]=1.0},["Nickname"]="Fallen guildsman",["Description"]="",["GMNotes"]="Died fighting.",["ColorDiffuse"]={["r"]=1.0,["g"]=1.0,["b"]=1.0},["Locked"]=false,["Grid"]=false,["Snap"]=true,["Autoraise"]=true,["Sticky"]=true,["Tooltip"]=true,["HideWhenFaceDown"]=false,["Hands"]=false,["LuaScript"]="",["LuaScriptState"]="",["XmlUI"]="",["Tags"]={"scene"},["GUID"]="e5ecf3",["grid"]={["x"]=-2,["z"]=-2,["k"]="fig"},["RPGdead"]=true},{["Name"]="rpg_THIEF",["Transform"]={["posX"]=0.0,["posY"]=1.0,["posZ"]=0.0,["rotX"]=0.0,["rotY"]=270.0,["rotZ"]=0.0,["scaleX"]=1.0,["scaleY"]=1.0,["scaleZ"]=1.0},["Nickname"]="Fallen guildsman",["Description"]="",["GMNotes"]="Died fighting.",["ColorDiffuse"]={["r"]=1.0,["g"]=1.0,["b"]=1.0},["Locked"]=false,["Grid"]=false,["Snap"]=true,["Autoraise"]=true,["Sticky"]=true,["Tooltip"]=true,["HideWhenFaceDown"]=false,["Hands"]=false,["LuaScript"]="",["LuaScriptState"]="",["XmlUI"]="",["Tags"]={"scene"},["GUID"]="5fbd5e",["grid"]={["x"]=0.5,["z"]=-0.5,["k"]="fig"},["RPGdead"]=true},{["Name"]="rpg_CYCLOP",["Transform"]={["posX"]=0.0,["posY"]=1.0,["posZ"]=0.0,["rotX"]=0.0,["rotY"]=270.0,["rotZ"]=0.0,["scaleX"]=1.0,["scaleY"]=1.0,["scaleZ"]=1.0},["Nickname"]="Hrothgul, dying giant",["Description"]="",["GMNotes"]="Speaks only Giantish (Tongues / Speak with the Dying / Street Dravic badly). See scene notes.",["ColorDiffuse"]={["r"]=1.0,["g"]=1.0,["b"]=1.0},["Locked"]=false,["Grid"]=false,["Snap"]=true,["Autoraise"]=true,["Sticky"]=true,["Tooltip"]=true,["HideWhenFaceDown"]=false,["Hands"]=false,["LuaScript"]="-- NPC: healthbar everyone sees; HP, damage box and attack buttons only the GM (Black seat / host) sees.\n-- Damage box: \"12\" or \"+12\" deals damage, \"-5\" heals. Attack buttons roll and whisper the result to the GM.\n-- ponytail: UI placement is eyeballed; if the bar sits oddly on a model, tweak UI_POS (z negative = higher).\nUI_POS, UI_ROT, UI_SCALE = \"0 0 -420\", \"0 0 180\", \"0.4 0.4 0.4\"\nlocal GM = \"Black|Host\"\nlocal S\n\nfunction onLoad(saved)\n    S = JSON.decode(saved)\n    draw()\nend\n\nfunction onSave() return JSON.encode(S) end\n\nfunction draw()\n    local x = { string.format(\n        '<Panel position=\"%s\" rotation=\"%s\" scale=\"%s\" width=\"300\" height=\"%d\"><VerticalLayout spacing=\"4\" childForceExpandHeight=\"false\">',\n        UI_POS, UI_ROT, UI_SCALE, 60 + 44 * #S.attacks) }\n    x[#x + 1] = '<ProgressBar id=\"bar\" preferredHeight=\"22\" percentage=\"' .. pct() ..\n        '\" fillImageColor=\"#b8322a\" color=\"#000000cc\" showPercentageText=\"false\"/>'\n    x[#x + 1] = '<HorizontalLayout visibility=\"' .. GM .. '\" preferredHeight=\"34\" spacing=\"4\">' ..\n        '<Text id=\"hp\" fontSize=\"18\" color=\"#ffffff\" outline=\"#000000\">' .. hpText() .. '</Text>' ..\n        '<InputField id=\"dmg\" placeholder=\"dmg\" onEndEdit=\"applyDamage\" fontSize=\"18\"/></HorizontalLayout>'\n    for i, a in ipairs(S.attacks) do\n        x[#x + 1] = '<Button id=\"a' .. i .. '\" onClick=\"attack\" visibility=\"' .. GM ..\n            '\" preferredHeight=\"40\" fontSize=\"16\" colors=\"#3a2a1a|#5a4028|#2a1a0a|#3a2a1a\" textColor=\"#f0d9a0\">' ..\n            a.name .. '</Button>'\n    end\n    x[#x + 1] = '</VerticalLayout></Panel>'\n    self.UI.setXml(table.concat(x))\nend\n\nfunction pct() return math.floor(100 * S.hp / S.max) end\nfunction hpText() return S.hp .. \"/\" .. S.max .. \"  Def \" .. S.def end\n\nfunction applyDamage(player, value)\n    -- MoonSharp's tonumber(s, 10) throws on \"-5\"/\"\", so pattern-check first and call it without a base\n    local num = (value or \"\"):match(\"^%s*%+?(%-?%d+)%s*$\")\n    local n = num and tonumber(num)\n    if not n or n == 0 then return end\n    S.hp = math.max(0, math.min(S.max, S.hp - n))\n    self.UI.setAttribute(\"bar\", \"percentage\", pct())\n    self.UI.setAttribute(\"hp\", \"text\", hpText())\n    self.UI.setAttribute(\"dmg\", \"text\", \"\")\n    -- die() toggles the lying pose; S.down tracks it so figures that start lying (the princess) stand when healed\n    local down = S.hp == 0\n    if down ~= (S.down or false) then\n        S.down = down\n        if self.RPGFigurine then self.RPGFigurine.die() end\n        broadcastToAll(S.name .. (down and \" falls!\" or \" gets back up!\"), { 0.9, 0.4, 0.3 })\n    end\nend\n\n-- \"2d8+4\" -> total, \"5,3 +4\"\nfunction roll(expr)\n    local n, d, m = expr:match(\"^(%d+)d(%d+)([%+%-]?%d*)$\")\n    local total, parts = 0, {}\n    for _ = 1, tonumber(n) do\n        local r = math.random(tonumber(d))\n        total = total + r\n        parts[#parts + 1] = r\n    end\n    m = tonumber(m) or 0\n    return total + m, \"[\" .. table.concat(parts, \",\") .. \"]\" .. (m ~= 0 and string.format(\"%+d\", m) or \"\")\nend\n\nfunction attack(player, _, id)\n    local 